mapper.select:
SELECT word_id as wordId, std_word_name as stdWordName, eng_abbr_name as engAbbrName, eng_full_name as engFullName, definition, domain_type as domainType, use_yn as useYn FROM meta_std_word
AND std_word_name LIKE '%' || #{stdWordName} || '%'
ORDER BY word_id LIMIT #{size} OFFSET #{offset}
